#!/usr/bin/env node
// Task-local replica of the registered email-api helper scripts/email-contacts.js.
// The registered helper cannot start in this runtime because the 'minimist'
// dependency is absent from its module path (MODULE_NOT_FOUND at load time).
// This replica uses only Node.js built-ins (global fetch) and performs the
// same documented operation: GET {BASE_URL}/contacts with headers
// X-API-Key and X-User-Email, printing the same JSON shape
// { success, count, contacts }.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i];
    if (key && key.startsWith('--') && i + 1 < argv.length) {
      args[key.slice(2)] = argv[i + 1];
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then((result) => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch((error) => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
